local phase = "new"
local leg = 0
local route = {
  {1125,-768,-116,0},
  {1143,-840,-116,0},
  {1186,-840,-116,300},
}
local function walk(e,next_leg)
  leg = next_leg; phase = "walking"
  local p = route[leg]
  e.self:SetRunning(true)
  e.self:MoveTo(p[1],p[2],p[3])
end
local function fail()
  if phase == "ended" then return end
  phase = "ended"; eq.stop_all_timers(); eq.signal(113486,3); eq.depop()
end
function event_spawn(e)
  if phase ~= "new" then return end
  walk(e,1)
end
function event_waypoint_depart(e)
  if phase ~= "walking" then return end
  local pause = route[leg][4]
  if pause > 0 then phase = "waiting"; eq.set_timer("expire",pause*1000)
  elseif leg < #route then walk(e,leg+1)
  else fail() end
end
function event_combat(e)
  if phase == "ended" then return end
  if e.joined then eq.pause_timer("expire") else eq.resume_timer("expire") end
end
function event_timer(e)
  if e.timer ~= "expire" or phase ~= "waiting" then return end
  if e.self:IsEngaged() then eq.pause_timer("expire"); return end
  fail()
end
function event_death_complete(e)
  if phase == "ended" then return end
  phase = "ended"; eq.stop_all_timers()
  e.self:Shout("Doldigun, you have caused us too much trouble. You are no longer welcome here! Show yourself!")
  eq.signal(113486,16)
end
